// Expo config plugin: signs Android release builds with the app's own key.
//
// The android/ folder is generated by `expo prebuild`, so the signing setup is
// added here instead of being edited by hand. The key and its passwords never
// enter the repository: they are read from Gradle properties, normally in
// %USERPROFILE%\.gradle\gradle.properties (see docs/development.md):
//
//   THROTTLE_KEYSTORE_FILE=C:/Users/me/keys/throttle-release.jks
//   THROTTLE_KEYSTORE_PASSWORD=...
//   THROTTLE_KEY_ALIAS=throttle
//   THROTTLE_KEY_PASSWORD=...
//
// Without these properties a release build fails instead of quietly using the
// debug key: an APK signed with another key cannot update the installed app.
const {withAppBuildGradle} = require('expo/config-plugins');

const SIGNING_CONFIG = `
        release {
            if (project.hasProperty('THROTTLE_KEYSTORE_FILE')) {
                storeFile file(THROTTLE_KEYSTORE_FILE)
                storePassword THROTTLE_KEYSTORE_PASSWORD
                keyAlias THROTTLE_KEY_ALIAS
                keyPassword THROTTLE_KEY_PASSWORD
            }
        }`;

const MARKER = 'THROTTLE_KEYSTORE_FILE';

const withReleaseSigning = (config) =>
  withAppBuildGradle(config, (gradle) => {
    let contents = gradle.modResults.contents;
    if (contents.includes(MARKER)) {
      return gradle;
    }
    // Add a release signing config after the debug one.
    contents = contents.replace(
      /(signingConfigs \{\s*debug \{[^}]*\})/,
      `$1${SIGNING_CONFIG}`,
    );
    // Use it for release builds.
    contents = contents.replace(
      /(release \{[^}]*?)signingConfig signingConfigs\.debug/,
      '$1signingConfig signingConfigs.release',
    );
    if (!contents.includes('signingConfig signingConfigs.release')) {
      throw new Error(
        'withReleaseSigning: android/app/build.gradle has an unexpected layout',
      );
    }
    // Stop a release build with a clear message if the key is not configured.
    // Checked only when a release task runs, so debug builds work without it.
    contents += `
gradle.taskGraph.whenReady { graph ->
    def releaseRequested = graph.allTasks.any { it.name.toLowerCase().contains('release') }
    if (releaseRequested && !project.hasProperty('${MARKER}')) {
        throw new GradleException("Release builds need the Throttle signing key. See docs/development.md, 'Building a release APK'.")
    }
}
`;
    gradle.modResults.contents = contents;
    return gradle;
  });

module.exports = withReleaseSigning;
